import { RAW_MORE } from './banks-more.js';

export const GENRES = [];

// Exactly 6 tiers: split the biggest group in half while short (groups run best-known first); fold extras into the last.
export function sixTiers(tiers) {
  while (tiers.length > 6) tiers[5].push(...tiers.splice(6, 1)[0]);
  while (tiers.length < 6) {
    const i = tiers.reduce((b, t, j) => (t.length > tiers[b].length ? j : b), 0);
    const g = tiers[i];
    tiers.splice(i, 1, g.slice(0, Math.ceil(g.length / 2)), g.slice(Math.ceil(g.length / 2)));
  }
  return tiers;
}
export const PROMPTS = [];

(function parse() {
  let genre = null, pending = null;
  for (const line of (RAW + '\n' + RAW_MORE).split('\n').map(l => l.trim()).filter(Boolean)) {
    if (line.startsWith('@')) {
      const [id, name, color] = line.slice(1).split('|');
      genre = GENRES.find(g => g.id === id);
      if (!genre) { genre = { id, name, color }; GENRES.push(genre); }
    } else if (!pending) {
      const people = line.startsWith('~');
      pending = { text: people ? line.slice(1) : line, people };
    } else {
      const tiers = line.split('|').map(g => g.split(',').map(a => a.trim()).filter(Boolean).map(a => a.split('/').map(s => s.trim()).filter(Boolean)));
      sixTiers(tiers);
      const n = PROMPTS.filter(p => p.genre === genre.id).length;
      PROMPTS.push({ id: `${genre.id}-${n}`, genre: genre.id, text: pending.text, people: pending.people, tiers });
      pending = null;
    }
  }
})();

// Letter prompts, built from existing banks: "Name an animal that starts with B". Each answer keeps its rarity tier.
(function letters() {
  const words = GENRES.find(g => g.id === 'words');
  const sources = [
    ['an animal', ['Name a mammal', 'Name a bird', 'Name a creature that lives in the sea', 'Name an insect', 'Name a reptile']],
    ['a country', ['Name a country,']],
    ['a fruit or vegetable', ['Name a fruit', 'Name a vegetable']],
  ];
  for (const [what, starts] of sources) {
    const src = PROMPTS.filter(p => starts.some(s => p.text.startsWith(s)));
    const byLetter = {};
    for (const p of src) p.tiers.forEach((g, tier) => g.forEach(a => {
      const L = a[0][0].toUpperCase();
      if (!/[A-Z]/.test(L)) return;
      (byLetter[L] ||= Array.from({ length: 6 }, () => []));
      if (!byLetter[L].flat().some(x => x[0] === a[0])) byLetter[L][tier].push(a.filter(x => x[0].toUpperCase() === L));
    }));
    const good = Object.entries(byLetter).filter(([, t]) => t.flat().length >= 18 && t.filter(g => g.length).length >= 4)
      .sort((a, b) => b[1].flat().length - a[1].flat().length).slice(0, 8);
    for (const [L, tiers] of good) {
      // keep tiers non-empty: borrow from the nearest neighbour
      for (let i = 0; i < 6; i++) if (!tiers[i].length) { const j = tiers.findIndex((g, k) => k > i && g.length > 1) ; if (j > 0) tiers[i].push(tiers[j].shift()); }
      if (tiers.some(g => !g.length)) continue;
      PROMPTS.push({ id: `words-${what.split(' ')[1]}-${L}`, genre: words.id, text: `Name ${what} whose name starts with the letter ${L}`, people: false, tiers });
    }
  }
})();
